 return (t.knownCommercialUrls??[]).includes(lead.url)||destinationPriority(t,lead)<=15||/(?:^|[\/_-])(?:products?|services?|offers?|packages?)(?:[\/_-]|$)/i.test(p)&&destinationPriority(t,lead)<40;
